string [] issues = selectIssues("project = MyProject AND linkedIssuePriority = 'High' AND priority != 'High' AND statusCategory != Done");
for(string issueKey in issues) {
  %issueKey%.priority = "High";
}

string [] issues = selectIssues("project = MyProject AND linkedByIssueProject = SUPPORT AND (labels IS EMPTY OR labels != support)");
for(string i in issues) {
  %issueKey%.labels += "support";
}

string [] issues = selectIssues("project = MyProject AND fixVersionsReleased > 0 AND statusCategory != Done");
for(string issueKey in issues) {
  addComment(issueKey, "admin", "This issue is in a version that was released. Should it be closed?");
}

string [] issues = selectIssues("project = MyProject AND fixVersionsReleased > 0 AND statusCategory != Done");
for(string issueKey in issues) {
  for(JRemoteIssueLink link in getWebLinksForIssue(issueKey)) {
      link.url = replace(link.url, "digitaltoucan", "appfire");
      updateWebLink(issueKey, link);
  }
}
